// (see [Core.SetUnstablePeriod]).
//
// It takes the parameters of [Core.STC] and returns [BadParam] for one out of
// range.
func (c *Core) STCLookback(optInFastPeriod, optInSlowPeriod, optInCyclePeriod int) (int, error) {
	if !fitsInt32(optInFastPeriod) {
		return 0, BadParam
	}
	if !fitsInt32(optInSlowPeriod) {
		return 0, BadParam
	}
	if !fitsInt32(optInCyclePeriod) {
		return 0, BadParam
	}
	lookback := c.stcLookback(int32(optInFastPeriod), int32(optInSlowPeriod), int32(optInCyclePeriod))
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

